int n, m, q;
if (!(cin >> n >> m >> q)) return 0;

// 用一个二维数组记录网格中每个位置对应的鱼的节点编号，0表示障碍
vector<vector<int>> grid(n + 1, vector<int>(m + 1, 0));
DSU dsu(q + 1); // 最多会有 q 条鱼被创建

int fish_cnt = 0;
int last_ans = 0;

int dx[] = {-1, 1, 0, 0};
int dy[] = {0, 0, -1, 1};

for (int i = 0; i < q; i++) {
    int op;
    cin >> op;
    if (op == 1) {
    int x_prime, y_prime, v;
    cin >> x_prime >> y_prime >> v;
    int x = x_prime ^ last_ans;
    int y = y_prime ^ last_ans;

    fish_cnt++;
    grid[x][y] = fish_cnt;
    dsu.val[fish_cnt] = v;

    vector<int> neighbors;
    for (int d = 0; d < 4; d++) {
    int nx = x + dx[d], ny = y + dy[d];
    if (nx >= 1 && nx <= n && ny >= 1 && ny <= m && grid[nx][ny] > 0) {
    neighbors.push_back(dsu.find(grid[nx][ny]));
    }
    }
    // 去重，防止同一个连通块被多次合并导致 sz 重复计算
    sort(neighbors.begin(), neighbors.end());
    neighbors.erase(unique(neighbors.begin(), neighbors.end()), neighbors.end());
