    cin >> x_prime >> y_prime;
    int x = x_prime ^ last_ans;
    int y = y_prime ^ last_ans;

    int id = grid[x][y];
    dsu.find(id); // 触发路径压缩更新 max_w

    int req_v = max(dsu.val[id], dsu.max_w[id]);
    last_ans = max(0, req_v - dsu.val[id]);
    cout << last_ans << "\n";
}
